using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using System.Drawing;using System.Collections.Generic;
using Grasshopper.Kernel;using Grasshopper.Kernel.Parameters;using Grasshopper.Kernel.Special;
class CreateStarter {
 [STAThread]static int Main(string[] args){string[] dirs={Path.Combine(args[1],"System"),Path.Combine(args[1],"Plug-ins","Grasshopper"),args[2]};AppDomain.CurrentDomain.AssemblyResolve+=delegate(object s,ResolveEventArgs e){foreach(string p in dirs){string f=Path.Combine(p,new AssemblyName(e.Name).Name+".dll");if(File.Exists(f))return Assembly.LoadFrom(f);}string gha=Path.Combine(args[2],new AssemblyName(e.Name).Name+".gha");if(File.Exists(gha))return Assembly.LoadFrom(gha);return null;};try{Build(args[0], false);Build(args[0], true);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Build(string folder, bool solution){Directory.CreateDirectory(folder);var objects=new List<IGH_DocumentObject>();
 var boundary=new Param_Curve(){NickName="Boundary"};var support=new Param_Curve(){NickName="Fixed edge"};var point=new Param_Point(){NickName="Load point"};
 IGH_DocumentObject[] ps={boundary,support,point};string[] notes={"BOUNDARY / select later\nRight-click the Curve parameter > Set one Curve. Select the closed outline on layer 01_Boundary. Keep it planar in World XY.","FIXED EDGE / select later\nSelect the vertical line on layer 02_Fixed_edge. This is a geometric selection only. No structural support has been created yet.","LOAD POINT / select later\nSelect the point on layer 03_Load_point. The intended force is (0, -100, 0) N. The reference arrow in Rhino is an illustration, not a TopOpt Load."};
 for(int i=0;i<3;i++){ps[i].CreateAttributes();ps[i].Attributes.Pivot=new PointF(350,160+i*180);objects.Add(ps[i]);var panel=new GH_Panel(){UserText=notes[i],NickName="Instructions"};panel.CreateAttributes();panel.Attributes.Pivot=new PointF(40,110+i*180);panel.Attributes.Bounds=new RectangleF(40,110+i*180,265,130);objects.Add(panel);}
 var title=new GH_Panel(){UserText="BLOCK 01 — UNDERSTAND THE PROBLEM\n120 x 60 mm plate; thickness 2 mm. Left edge fixed in X and Y. Downward force 100 N at (120, 30, 0) mm.\n\nFirst observe and predict. Geometry parameters start empty. No TopOpt solver or automatic calculation is included.",NickName="Lesson 01"};title.CreateAttributes();title.Attributes.Pivot=new PointF(530,110);title.Attributes.Bounds=new RectangleF(530,110,350,250);objects.Add(title);
 var slider=new GH_NumberSlider(){NickName="Cell size (mm)"};slider.CreateAttributes();slider.Attributes.Pivot=new PointF(350,700);slider.Slider.Type=Grasshopper.GUI.Base.GH_SliderAccuracy.Integer;slider.Slider.Minimum=3;slider.Slider.Maximum=12;slider.SetSliderValue(6);objects.Add(slider);
 if(solution){var domain=new TopoptLab.GH.DomainComponent();domain.CreateAttributes();domain.Attributes.Pivot=new PointF(780,650);domain.Params.Input[0].AddSource(boundary);domain.Params.Input[3].AddSource(slider);objects.Add(domain);}
 foreach(var obj in objects){var panel=obj as GH_Panel;if(panel!=null && panel.NickName=="Lesson 01")panel.UserText="LESSON 02 / BUILD THE DOMAIN\nOpen the shared lesson 01 Rhino model. Set Boundary to the closed outline on 01_Boundary (120 x 60 mm).\n\n"+(solution?"WIRED SOLUTION: Boundary -> Domain B; Cell size -> Domain h. Select the boundary to obtain 200 cells at h=6.":"STARTER: Add TopOpt Domain. Wire Boundary -> B and Cell size -> h. Leave H and K empty; Plane stays World XY.")+"\n\nTry h=12, 6, 3; then restore 6 and save. Fixed edge and Load point are reserved for lesson 03. No structural solver is included.";}
 string basename=solution?"lesson02_solution":"lesson02_starter";
 var archive=new GH_IO.Serialization.GH_Archive();var def=archive.CreateTopLevelNode("Definition");def.SetVersion("plugin_version",1,0,7);var header=def.CreateChunk("DocumentHeader");header.SetGuid("DocumentID",Guid.NewGuid());header.SetString("Preview","Shaded");header.SetInt32("PreviewMeshType",1);
 var props=new GH_DocumentProperties(){ProjectFileName=basename+".gh",Description="Lesson 02: Domain discretisation. Select the shared model boundary. No structural solver.",ViewTarget=new Point(420,300),ZoomFactor=.65f};if(!props.Write(def))throw new Exception("Properties write failed");def.CreateChunk("RcpLayout").SetInt32("GroupCount",0);def.CreateChunk("GHALibraries").SetInt32("Count",0);var list=def.CreateChunk("DefinitionObjects");list.SetInt32("ObjectCount",objects.Count);
 for(int i=0;i<objects.Count;i++){var obj=objects[i];obj.Attributes.PerformLayout();var ch=list.CreateChunk("Object",i);ch.SetGuid("GUID",obj.ComponentGuid);ch.SetString("Name",obj.Name);if(!obj.Write(ch.CreateChunk("Container")))throw new Exception("Object write failed");}
 foreach(var ext in new[]{".gh",".ghx"}){var file=Path.Combine(folder,basename+ext);if(!archive.WriteToFile(file,true,false))throw new Exception("Write failed");var read=new GH_IO.Serialization.GH_Archive();if(!read.ReadFromFile(file))throw new Exception("Readback failed");var definition=read.GetRootNode.FindChunk("Definition");var properties=new GH_DocumentProperties();if(!properties.Read(definition))throw new Exception("Properties readback failed");var items=definition.FindChunk("DefinitionObjects");for(int i=0;i<objects.Count;i++){var clone=(IGH_DocumentObject)Activator.CreateInstance(objects[i].GetType());clone.CreateAttributes();if(!clone.Read(items.FindChunk("Object",i).FindChunk("Container")))throw new Exception("Object readback failed");}Console.WriteLine("PASS SDK readback: "+file+" / "+objects.Count+" native objects");}
 }
}
